float sdHexPrism(vec3 p, vec2 h) {
  vec3 q = abs(p);
  return max(q.z - h.y, max((q.x * 0.866025 + q.y * 0.5), q.y) - h.x);
}
float map(vec3 p) {
  p.z += time * 0.9;
  vec3 q = p;
  vec2 r = vec2(1.732, 1.0);
  vec2 h = r * 0.5;
  vec2 a = mod(q.xy, r) - h;
  vec2 b = mod(q.xy - h, r) - h;
  vec2 g = dot(a, a) < dot(b, b) ? a : b;
  return sdHexPrism(vec3(g, q.z), vec2(0.48, 100.0));
}
